"use client";

import * as React from "react";

import { AsciiVRule } from "@/components/ascii/ascii-box";
import { cn } from "@/lib/utils";

type ResizableContextValue = {
  leftWidth: number;
  rightWidth: number;
  onHandlePointerDown: (event: React.PointerEvent) => void;
  onHandleKeyDown: (event: React.KeyboardEvent) => void;
};

const ResizableContext = React.createContext<ResizableContextValue | null>(
  null
);

function useResizableContext(component: string) {
  const context = React.useContext(ResizableContext);
  if (!context) {
    throw new Error(`${component} must be used within <ResizablePanelGroup>`);
  }
  return context;
}

/**
 * Manages a draggable split between two children. AsciiBox frames are
 * fixed-character-width (their borders are literal repeated "-" glyphs),
 * so the split is tracked in whole characters rather than fluid pixels —
 * dragging regrows/shrinks each panel's ASCII border one column at a time.
 * Renders a `<div>` element.
 */
function ResizablePanelGroup({
  className,
  totalWidth = 61,
  defaultLeftWidth = 30,
  minWidth = 12,
  ...props
}: React.ComponentProps<"div"> & {
  totalWidth?: number;
  defaultLeftWidth?: number;
  minWidth?: number;
}) {
  const [leftWidth, setLeftWidth] = React.useState(defaultLeftWidth);
  const groupRef = React.useRef<HTMLDivElement>(null);
  const draggingRef = React.useRef(false);
  const maxLeftWidth = totalWidth - minWidth - 1;

  const clamp = React.useCallback(
    (value: number) => Math.min(maxLeftWidth, Math.max(minWidth, value)),
    [maxLeftWidth, minWidth]
  );

  const onHandlePointerDown = React.useCallback((event: React.PointerEvent) => {
    event.preventDefault();
    draggingRef.current = true;
    (event.currentTarget as HTMLElement).setPointerCapture(event.pointerId);
  }, []);

  const onHandleKeyDown = React.useCallback(
    (event: React.KeyboardEvent) => {
      const step = event.shiftKey ? 5 : 1;
      if (event.key === "ArrowLeft") {
        event.preventDefault();
        setLeftWidth((w) => clamp(w - step));
      } else if (event.key === "ArrowRight") {
        event.preventDefault();
        setLeftWidth((w) => clamp(w + step));
      }
    },
    [clamp]
  );

  React.useEffect(() => {
    function onPointerMove(event: PointerEvent) {
      if (!draggingRef.current || !groupRef.current) return;
      const rect = groupRef.current.getBoundingClientRect();
      const percent = (event.clientX - rect.left) / rect.width;
      setLeftWidth(clamp(Math.round(totalWidth * percent)));
    }
    function onPointerUp() {
      draggingRef.current = false;
    }
    window.addEventListener("pointermove", onPointerMove);
    window.addEventListener("pointerup", onPointerUp);
    return () => {
      window.removeEventListener("pointermove", onPointerMove);
      window.removeEventListener("pointerup", onPointerUp);
    };
  }, [clamp, totalWidth]);

  return (
    <ResizableContext.Provider
      value={{
        leftWidth,
        rightWidth: totalWidth - leftWidth - 1,
        onHandlePointerDown,
        onHandleKeyDown,
      }}
    >
      <div
        ref={groupRef}
        data-slot="resizable-panel-group"
        className={cn("inline-flex w-fit self-start font-mono", className)}
        {...props}
      />
    </ResizableContext.Provider>
  );
}

function ResizablePanel({
  className,
  side,
  children,
  ...props
}: Omit<React.ComponentProps<"div">, "children"> & {
  side: "start" | "end";
  children: (chWidth: number) => React.ReactNode;
}) {
  const { leftWidth, rightWidth } = useResizableContext("ResizablePanel");
  const chWidth = side === "start" ? leftWidth : rightWidth;

  return (
    <div
      data-slot="resizable-panel"
      className={cn("shrink-0", className)}
      {...props}
    >
      {children(chWidth)}
    </div>
  );
}

function ResizableHandle({ className, ...props }: React.ComponentProps<"div">) {
  const { onHandlePointerDown, onHandleKeyDown } =
    useResizableContext("ResizableHandle");

  return (
    <div
      data-slot="resizable-handle"
      role="separator"
      aria-orientation="vertical"
      tabIndex={0}
      onPointerDown={onHandlePointerDown}
      onKeyDown={onHandleKeyDown}
      className={cn(
        "relative z-10 -mx-[1ch] w-[1ch] shrink-0 cursor-col-resize touch-none bg-background text-ascii-comment outline-none select-none hover:text-primary focus-visible:text-primary active:text-primary",
        className
      )}
      {...props}
    >
      {/* Absolutely positioned so the rule's glyph filler can't add
       * height of its own — the handle tracks the tallest panel. */}
      <AsciiVRule className="pointer-events-none absolute inset-0 text-inherit" />
    </div>
  );
}

export { ResizableHandle, ResizablePanel, ResizablePanelGroup };

"use client";

import * as React from "react";

import { useAsciiChars } from "@/components/ascii/ascii-chars";
import {
  type AsciiChars,
  bottomBorder,
  dividerBorder,
  fill,
  junctionGlyph,
  topBorder,
  vColumn,
  vGlyph,
} from "@/lib/ascii";
import { cn } from "@/lib/utils";

type Tone = "primary" | "soft";

/** Which line of the glyph set a rule draws with. */
type AsciiLine = keyof Omit<AsciiChars, "junction">;

/* Every ASCII frame in the app shares one border color (matching the
 * inputs' and menus' rest-state frames). The tone axis is kept as API
 * so emphasis can be reintroduced without touching call sites. */
const toneClass: Record<Tone, string> = {
  primary: "text-primary/60",
  soft: "text-primary/60",
};

const AsciiBoxContext = React.createContext<{
  width: number;
  tone: Tone;
  /** Background utility class of the box surface — dividers repaint it
   * over the absolute side rules so intersections show only junctions. */
  bg: string;
  /** Fluid boxes take their width from CSS, so dividers are drawn as
   * clipped rules instead of fixed-length strings. */
  fluid: boolean;
}>({
  width: 40,
  tone: "soft",
  bg: "bg-card",
  fluid: false,
});

/** The junction glyph ("+" by default) — for corners and intersections
 * drawn outside a full AsciiBox (layout frames, fluid borders). */
function AsciiJunction({
  className,
  ...props
}: Omit<React.ComponentProps<"span">, "children">) {
  const chars = useAsciiChars();
  return (
    <span aria-hidden className={cn("select-none", className)} {...props}>
      {junctionGlyph(chars)}
    </span>
  );
}

/** One glyph of a vertical edge — for single-row frames (inputs,
 * menu items, table rows) that draw their own sides per row. */
function AsciiSide({
  side = "left",
  row = 0,
  className,
  ...props
}: Omit<React.ComponentProps<"span">, "children"> & {
  side?: "left" | "right";
  row?: number;
}) {
  const chars = useAsciiChars();
  return (
    <span aria-hidden className={cn("select-none", className)} {...props}>
      {vGlyph(chars[side], row)}
    </span>
  );
}

/** A fixed-width "+----+" edge row for frames sized in characters —
 * the top (optionally titled) or bottom border of an input, menu,
 * avatar… Rendered as a block span so it can sit inside buttons. */
function AsciiEdge({
  edge,
  width,
  title,
  className,
  ...props
}: Omit<React.ComponentProps<"span">, "children" | "title"> & {
  edge: "top" | "bottom";
  width: number;
  title?: string;
}) {
  const chars = useAsciiChars();
  return (
    <span
      aria-hidden
      className={cn("block select-none whitespace-pre", className)}
      {...props}
    >
      {edge === "top"
        ? topBorder(width, title, chars)
        : bottomBorder(width, chars)}
    </span>
  );
}

/** A column of side glyphs that stretches to match its sibling's
 * height via flex `items-stretch` — real glyphs, clipped by overflow. */
function AsciiVRule({
  tone = "soft",
  side = "left",
  className,
}: {
  tone?: Tone;
  side?: "left" | "right";
  className?: string;
}) {
  const chars = useAsciiChars();
  return (
    <div
      aria-hidden
      className={cn(
        "w-[1ch] shrink-0 select-none overflow-hidden",
        toneClass[tone],
        className
      )}
    >
      <pre className="m-0 font-mono">{vColumn(300, chars[side])}</pre>
    </div>
  );
}

/** One or more literal empty text rows — vertical padding that stays
 * on the character grid instead of arbitrary CSS lengths. */
function AsciiPad({
  rows = 1,
  className,
}: {
  rows?: number;
  className?: string;
}) {
  return (
    <div aria-hidden className={cn("select-none whitespace-pre", className)}>
      {Array.from({ length: rows }, () => " ").join("\n")}
    </div>
  );
}

type AsciiBoxProps = Omit<React.ComponentProps<"div">, "title"> & {
  width: number;
  title?: string;
  tone?: Tone;
  contentClassName?: string;
  /** Empty text rows rendered above and below the content. */
  padY?: number;
  /** Background utility class of the box surface. Pass this instead of a
   * bg-* class in className so dividers can repaint it at intersections. */
  bg?: string;
  /** Size the box with CSS (w-*, max-w-*) instead of `width`: the edge
   * rows become clipped rules that follow the container, so the box can
   * be `w-full` on a narrow screen. `width` is then only the fallback
   * used when no width class is given. */
  fluid?: boolean;
};

function AsciiBox({
  width,
  title,
  tone = "soft",
  bg = "bg-card",
  className,
  contentClassName,
  padY = 0,
  fluid = false,
  children,
  ...props
}: AsciiBoxProps) {
  const chars = useAsciiChars();
  return (
    <AsciiBoxContext.Provider value={{ width, tone, bg, fluid }}>
      <div
        data-slot="ascii-box"
        className={cn(
          "inline-flex flex-col font-mono text-card-foreground text-sm",
          bg,
          className
        )}
        style={fluid ? undefined : { width: `${width}ch` }}
        {...props}
      >
        {fluid ? (
          <div
            aria-hidden
            className={cn("flex select-none whitespace-pre", toneClass[tone])}
          >
            <AsciiJunction className="shrink-0" />
            {title ? (
              <>
                <AsciiRule
                  line="top"
                  tone={tone}
                  className="w-[2ch] shrink-0 text-inherit"
                />
                <span className="shrink-0">{` ${title} `}</span>
              </>
            ) : null}
            <AsciiRule
              line="top"
              tone={tone}
              className="min-w-0 flex-1 text-inherit"
            />
            <AsciiJunction className="shrink-0" />
          </div>
        ) : (
          <div
            aria-hidden
            className={cn("select-none whitespace-pre", toneClass[tone])}
          >
            {topBorder(width, title, chars)}
          </div>
        )}
        <div className="relative">
          <AsciiVRule
            tone={tone}
            side="left"
            className="absolute inset-y-0 left-0"
          />
          {padY > 0 && <AsciiPad rows={padY} />}
          <div className={cn("min-w-0 px-[2ch]", contentClassName)}>
            {children}
          </div>
          {padY > 0 && <AsciiPad rows={padY} />}
          <AsciiVRule
            tone={tone}
            side="right"
            className="absolute inset-y-0 right-0"
          />
        </div>
        {fluid ? (
          <AsciiHBorder line="bottom" tone={tone} />
        ) : (
          <div
            aria-hidden
            className={cn("select-none whitespace-pre", toneClass[tone])}
          >
            {bottomBorder(width, chars)}
          </div>
        )}
      </div>
    </AsciiBoxContext.Provider>
  );
}

/** A "+---+" divider spanning the box's full content width, flanked
 * by one empty text row on each side (disable with pad={false}) —
 * for separating sections (header/content/footer) inside an AsciiBox. */
function AsciiBoxDivider({
  className,
  pad = true,
}: {
  className?: string;
  pad?: boolean;
}) {
  const { width, tone, bg, fluid } = React.useContext(AsciiBoxContext);
  const chars = useAsciiChars();
  return (
    <div
      aria-hidden
      className={cn(
        "-mx-[2ch] select-none whitespace-pre",
        toneClass[tone],
        className
      )}
    >
      {pad && <div> </div>}
      {/* Positioned above the box's absolute side rules and repainting
       * the surface, so the intersection cells show only junctions. */}
      <div className={cn("relative z-10", bg)}>
        {fluid ? (
          <AsciiHBorder line="divider" tone={tone} />
        ) : (
          <span>{dividerBorder(width, chars)}</span>
        )}
      </div>
      {pad && <div> </div>}
    </div>
  );
}

/** A single side-glyph-flanked line — for list-style rows (menus, table
 * rows) that need their own hover/selection background per row. */
function AsciiBoxRow({
  className,
  contentClassName,
  children,
  ...props
}: React.ComponentProps<"div"> & { contentClassName?: string }) {
  const { tone } = React.useContext(AsciiBoxContext);
  return (
    <div className={cn("-mx-[2ch] flex items-center", className)} {...props}>
      <AsciiSide side="left" className={cn("shrink-0", toneClass[tone])} />
      <div className={cn("min-w-0 flex-1 px-[1ch]", contentClassName)}>
        {children}
      </div>
      <AsciiSide side="right" className={cn("shrink-0", toneClass[tone])} />
    </div>
  );
}

/** A fluid single-character-tall rule for contexts where the exact
 * character width isn't known ahead of time (e.g. spans a flexible
 * container). Renders real repeated glyphs, clipped by overflow.
 *
 * Draws with the theme's `divider` line (horizontal) or `left` line
 * (vertical) unless `line` picks another edge; `char` overrides the
 * theme entirely. */
function AsciiRule({
  className,
  char,
  line,
  tone = "soft",
  orientation = "horizontal",
}: {
  className?: string;
  char?: string;
  line?: AsciiLine;
  tone?: Tone;
  orientation?: "horizontal" | "vertical";
}) {
  const chars = useAsciiChars();
  const vertical = orientation === "vertical";
  const seq = char ?? chars[line ?? (vertical ? "left" : "divider")];
  return (
    <div
      aria-hidden
      className={cn(
        "select-none overflow-hidden whitespace-pre text-nowrap",
        toneClass[tone],
        className
      )}
    >
      {vertical ? vColumn(300, seq) : fill(400, seq)}
    </div>
  );
}

/** A fluid "+----+" row: junction, a horizontal line that fills the
 * available width, junction. For box edges whose width is set by
 * layout rather than a character count. */
function AsciiHBorder({
  line = "top",
  tone = "soft",
  className,
  ...props
}: Omit<React.ComponentProps<"div">, "children"> & {
  line?: AsciiLine;
  tone?: Tone;
}) {
  return (
    <div
      aria-hidden
      className={cn("flex select-none", toneClass[tone], className)}
      {...props}
    >
      <AsciiJunction className="shrink-0" />
      <AsciiRule line={line} tone={tone} className="min-w-0 flex-1" />
      <AsciiJunction className="shrink-0" />
    </div>
  );
}

export type { AsciiLine };
export {
  AsciiBox,
  AsciiBoxContext,
  AsciiBoxDivider,
  AsciiBoxRow,
  AsciiEdge,
  AsciiHBorder,
  AsciiJunction,
  AsciiPad,
  AsciiRule,
  AsciiSide,
  AsciiVRule,
};

"use client";

import * as React from "react";

import { type AsciiChars, DEFAULT_ASCII_CHARS } from "@/lib/ascii";

/** The glyph set every framed component draws its edges from. The
 * default value means components work with no provider at all — they
 * render the classic "+", "-" and "|" frame. */
const AsciiCharsContext = React.createContext<AsciiChars>(DEFAULT_ASCII_CHARS);

/** Supplies a fixed glyph set to every component beneath it — the
 * static entry point for a project that wants, say, "<|>" edges without
 * the styling page's localStorage-backed AsciiThemeProvider. Any key
 * left out keeps its default. */
function AsciiCharsProvider({
  chars,
  children,
}: {
  chars: Partial<AsciiChars>;
  children: React.ReactNode;
}) {
  const value = React.useMemo<AsciiChars>(
    () => ({ ...DEFAULT_ASCII_CHARS, ...chars }),
    [chars]
  );
  return (
    <AsciiCharsContext.Provider value={value}>
      {children}
    </AsciiCharsContext.Provider>
  );
}

/** The active border glyph set. */
function useAsciiChars(): AsciiChars {
  return React.useContext(AsciiCharsContext);
}

export { AsciiCharsContext, AsciiCharsProvider, useAsciiChars };

/** The glyph set every ASCII frame in the library is drawn from.
 *
 * Line entries (`top`, `bottom`, `left`, `right`, `divider`) may be a
 * single character or a sequence that repeats to fill the run — `<|>`
 * draws `<|><|><|>…`. Vertical lines repeat one character per row.
 * `junction` is always exactly one character: it sits at corners and
 * wherever a divider meets a side. */
export type AsciiChars = {
  /** Top edge of a box, repeats horizontally. */
  top: string;
  /** Bottom edge of a box, repeats horizontally. */
  bottom: string;
  /** Left edge of a box, repeats vertically (one char per row). */
  left: string;
  /** Right edge of a box, repeats vertically (one char per row). */
  right: string;
  /** Interior horizontal rules: section dividers, separators, table
   * row dividers. Repeats horizontally. */
  divider: string;
  /** Corners and intersections. Single character. */
  junction: string;
};

export const DEFAULT_ASCII_CHARS: AsciiChars = {
  top: "-",
  bottom: "-",
  left: "|",
  right: "|",
  divider: "-",
  junction: "+",
};

/** Repeats `seq` to exactly `n` characters (truncating a partial
 * final repeat). An empty sequence falls back to a space so the
 * layout keeps its width. */
export function fill(n: number, seq = "-") {
  const count = Math.max(n, 0);
  if (count === 0) {
    return "";
  }
  const unit = seq.length > 0 ? seq : " ";
  return unit.repeat(Math.ceil(count / unit.length)).slice(0, count);
}

/** @deprecated use `fill` — kept as an alias for existing call sites. */
export function hRepeat(n: number, char = "-") {
  return fill(n, char);
}

/** The glyph a vertical sequence shows on a given row. */
export function vGlyph(seq: string, row = 0) {
  if (seq.length === 0) {
    return " ";
  }
  return seq[row % seq.length] ?? " ";
}

/** `rows` glyphs of a vertical sequence, one per line. */
export function vColumn(rows: number, seq = "|") {
  const lines: string[] = [];
  for (let row = 0; row < rows; row += 1) {
    lines.push(vGlyph(seq, row));
  }
  return lines.join("\n");
}

/** A single junction glyph — sequences are trimmed to their first
 * character, an empty string falls back to the default. */
export function junctionGlyph(chars: AsciiChars) {
  return chars.junction.length > 0
    ? chars.junction[0]
    : DEFAULT_ASCII_CHARS.junction;
}

export function topBorder(
  width: number,
  title?: string,
  chars: AsciiChars = DEFAULT_ASCII_CHARS
) {
  const j = junctionGlyph(chars);
  if (!title) {
    return `${j}${fill(width - 2, chars.top)}${j}`;
  }
  const label = ` ${title} `;
  const left = 2;
  const right = Math.max(width - 2 - left - label.length, 1);
  return `${j}${fill(left, chars.top)}${label}${fill(right, chars.top)}${j}`;
}

export function bottomBorder(
  width: number,
  chars: AsciiChars = DEFAULT_ASCII_CHARS
) {
  const j = junctionGlyph(chars);
  return `${j}${fill(width - 2, chars.bottom)}${j}`;
}

export function dividerBorder(
  width: number,
  chars: AsciiChars = DEFAULT_ASCII_CHARS
) {
  const j = junctionGlyph(chars);
  return `${j}${fill(width - 2, chars.divider)}${j}`;
}

/** Divider row for a table: a junction at every column boundary,
 * divider glyphs exactly as wide as each column. Its junctions land
 * on the side-glyph positions of rows built as `|cell|cell|…|` with
 * the same widths. */
export function columnDivider(
  widths: number[],
  chars: AsciiChars = DEFAULT_ASCII_CHARS
) {
  const j = junctionGlyph(chars);
  return `${j}${widths.map((w) => fill(w, chars.divider)).join(j)}${j}`;
}

/** Total character width of a table row (and its dividers):
 * one side glyph per boundary plus the column widths. */
export function tableRowWidth(widths: number[]) {
  return widths.reduce((sum, w) => sum + w, 0) + widths.length + 1;
}
